ft);overflow:hidden}\n.fill{display:block;height:100%;border-radius:2px;background:var(--accent)}\n.card[data-size=\"3x6\"] .sub,.card[data-size=\"6x6\"] .sub{display:block}\n.card[data-size=\"3x6\"] .bar,.card[data-size=\"6x6\"] .bar{display:block}\n.card[data-size=\"3x6\"] .nmt,.card[data-size=\"6x6\"] .nmt{white-space:normal;overflow-wrap:anywhere;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical}\n\n.cell{width:100%;height:22px;min-width:0;padding:0;display:flex;align-items:center;justify-content:center;border:1px dashed var(--muted);border-radius:7px;background:transparent;color:var(--on-accent);font-size:12px;font-weight:700;line-height:1}\n.cell:not(.on):hover{background:var(--soft)}\n.cell.now{border:1.5px solid var(--accent)}\n.cell.on{border:1px solid var(--accent);background:var(--accent)}\n.card[data-size=\"6x3\"] .cell{height:24px}\n.card[data-size=\"3x6\"] .cell{height:30px;font-size:14px}\n.card[data-size=\"6x6\"] .cell{height:34px;font-size:15px}\n\n.card[data-size=\"6x3\"] .dayhead,.card[data-size=\"6x3\"] .hrow,.card[data-size=\"6x6\"] .dayhead,.card[data-size=\"6x6\"] .hrow{grid-template-columns:96px repeat(7,minmax(0,1fr)) 46px;column-gap:4px;padding:4px 8px}\n.card[data-size=\"6x3\"] .sp,.card[data-size=\"6x6\"] .sp{display:block}\n.card[data-size=\"6x3\"] .namec,.card[data-size=\"6x3\"] .cnt,.card[data-size=\"6x6\"] .namec,.card[data-size=\"6x6\"] .cnt{grid-column:auto;grid-row:auto}\n.card[data-size=\"6x6\"] .hrow{padding-top:8px;padding-bottom:8px}\n\n.empty{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;min-height:100%;padding:12px;text-align:center;color:var(--muted)}\n.empty p{margin:0}\n\n.form{overflow:auto;gap:6px}\n.fh{display:flex;align-items:center;gap:8px;flex:none}\n.fh h2{margin:0;font-size:14px;font-weight:700;color:var(--ink)}\n.lbl{flex:none;font-size:11px;color:var(--muted)}\n.inp{flex:none;width:100%;height:32px;padding:0 8px;border:1px solid var(--line);border-radius:8