const WD=['日','一','二','三','四','五','六'];
function pad2(n){return n<10?'0'+n:''+n;}
function parseDay(str){const p=String(str).split('-');return new Date(+p[0],+p[1]-1,+p[2]);}
function fmtDay(dt){return dt.getFullYear()+'-'+pad2(dt.getMonth()+1)+'-'+pad2(dt.getDate());}
function addDays(str,n){const dt=parseDay(str);dt.setDate(dt.getDate()+n);return fmtDay(dt);}
function mdOf(str){const p=String(str).split('-');return p[1]+'/'+p[2];}
function weekdayOf(str){return WD[parseDay(str).getDay()];}
function clampT(t){return Math.min(7,Math.max(1,Math.round(Number(t))||1));}

// 首次加载：只放入用户指定的三个习惯（名称可改、目标可改），打卡记录为空
function initialize(s){
  if(s&&Array.isArray(s.habits))return s;
  const base=s&&typeof s==='object'?s:{};
  return {
    ...base,
    habits:[
      {id:'h-sleep',name:'早睡',target:5},
      {id:'h-stretch',name:'拉伸',target:5},
      {id:'h-read',name:'阅读',target:5}
    ],
    logs:base.logs||{}
  };
}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,percent}=ctx;
  const habits=Array.isArray(state.habits)?state.habits:[];
  const logs=state.logs||{};
  const today=day();
  const off=Math.max(0,Number(ui.off)||0);
  const end=addDays(today,-7*off);
  const days=[];
  for(let i=6;i>=0;i--)days.push(addDays(end,-i));
  const view=ui.view==='edit'?'edit':'list';

  function kids(a){return a.filter(x=>x!==null&&x!==undefined&&x!==false);}

  // 打卡 / 补记 / 撤销：只改动这一天这一项，其余记录原样保留
  function toggle(hid,d){
    ui.msg='';
    update(s=>{
      const all={...(s.logs||{})};
      const m={...(all[hid]||{})};
      if(m[d])delete m[d];else m[d]=1;
      all[hid]=m;
      return {...s,logs:all};
    }).catch(()=>{ui.msg='保存失败，请重试';redraw();});
  }

  function openEdit(h){
    ui.view='edit';ui.err='';ui.confirmDel=false;ui.saving=false;
    ui.draft=h?{id:h.id,name:h.name,target:clampT(h.target)}:{id:null,nid:uid(),name:'',target:3};
    redraw();
  }
  function closeEdit(){
    ui.view='list';ui.err='';ui.confirmDel=false;ui.saving=false;ui.draft=null;
    redraw();
  }
  function nextUi(){
    return {view:'list',off:off,draft:null,err:'',msg:'',confirmDel:false,saving:false};
  }
  function saveFail(){ui.saving=false;ui.err='保存失败，请重试';redraw();}

  function saveHabit(){
    const d=ui.draft;
    if(!d||ui.saving)return;
    const name=String(d.name||'').trim();
    const t=Math.round(Number(d.target));
    if(!name){ui.err='请输入习惯名称';redraw();return;}
    if(name.length>24){ui.err='名称请控制在 24 字以内';redraw();return;}
    if(!(t>=1&&t<=7)){ui.err='每周目标需在 1–7 次之间';redraw();return;}
    ui.saving=true;ui.err='';
    commit(s=>{
      const hs=Array.isArray(s.habits)?s.habits:[];
      if(d.id)return {...s,habits:hs.map(h=>h.id===d.id?{...h,name:name,target:t}:h)};
      if(hs.some(h=>h.id===d.nid))return s;
      return {...s,habits:hs.concat([{id:d.nid,name:name,target:t}])};
    },nextUi()).catch(saveFail);
  }

  function deleteHabit(){
    const d=ui.draft;
    if(!d||!d.id||ui.saving)return;
    const id=d.id;
    ui.saving=true;
    commit(s=>{
      const all={...(s.logs||{})};
      delete all[id];
      return {...s,habits:(Array.isArray(s.habits)?s.habits:[]).filter(h=>h.id!==id),logs:all};
    },nextUi()).catch(saveFail);
  }


  function renderHeader(){
    const lbl=off===0?'最近七天':'往前 '+off+' 周';
    const prev=el('button',{type:'button',class:'ib','aria-label':'查看更早的一周',title:'更早一周',onclick:()=>{ui.off=off+1;redraw();}},'‹');
    const next=el('button',{type:'button',class:'ib','aria-label':'查看较新的一周',title:'较新一周',disabled:off===0,onclick:()=>{ui.off=Math.max(0,off-1);redraw();}},'›');
    const range=el('div',{class:'range'},el('b',{},lbl),el('span',{},mdOf(days[0])+' – '+mdOf(days[6])));
    const add=el('button',{type:'button',class:'add','aria-label':'添加习惯',onclick:()=>openEdit(null)},el('span',{},'＋'),el('span',{class:'addtxt'},' 添加'));
    return el('div',{class:'hd'},el('h1',{class:'title'},'习惯打卡'),el('div',{class:'nav'},prev,range,next),add);
  }

  function renderHead(){
    const cells=days.map(d=>{
      const a={class:'dh'+(d===today?' today':'')};
      if(d===today)a['aria-current']='date';
      return el('div',a,el('span',{class:'wd'},weekdayOf(d)),el('span',{class:'dn'},String(parseDay(d).getDate())));
    });
    return el('div',{class:'dayhead'},el('div',{class:'sp'}),...cells,el('div',{class:'sp'}));
  }

  function renderRow(h){
    const t=clampT(h.target);
    const m=logs[h.id]||{};
    const cnt=days.filter(d=>m[d]).length;
    const total=Object.keys(m).length;
    const hit=cnt>=t;
    const nameBtn=el('button',{type:'button',class:'nm','aria-label':'编辑习惯 '+h.name,title:h.name+'（点击编辑）',onclick:()=>openEdit(h)},
      el('span',{class:'nmt'},h.name),el('span',{class:'pen','aria-hidden':'true'},'✎'));
    const fill=el('span',{class:'fill'});
    fill.style.width=percent(Math.min(cnt,t),t)+'%';
    const namec=el('div',{class:'namec'},nameBtn,el('span',{class:'sub'},'累计 '+total+' 次'),el('span',{class:'bar'},fill));
    const cells=days.map(d=>{
      const on=!!m[d];
      const cls='cell'+(on?' on':'')+(d===today?' now':'');
      const act=on?'已完成，点击撤销':(d===today?'未完成，点击打卡':'未完成，点击补记');
      return el('button',{type:'button',class:cls,'aria-pressed':on?'true':'false','aria-label':h.name+' '+mdOf(d)+' '+act,title:mdOf(d)+' '+act,onclick:()=>toggle(h.id,d)},on?'✓':'');
    });
    const cntc=el('div',{class:'cnt'+(hit?' hit':''),title:'这7天完成 '+cnt+' 次，目标 '+t+' 次'},el('b',{},cnt+'/'+t+(hit?' ✓':'')));
    return el('div',{class:'hrow'},namec,...cells,cntc);
  }

  function renderList(){
    const body=habits.length?[renderHead(),...habits.map(renderRow)]:[
      el('div',{class:'empty'},el('p',{},'还没有习惯。'),el('button',{type:'button',class:'btn pri',onclick:()=>openEdit(null)},'添加第一个习惯'))
    ];
    return el('div',{class:'main'},...kids([
      renderHeader(),
      ui.msg?el('div',{class:'msg',role:'alert'},'⚠ '+ui.msg):null,
      el('div',{class:'list'},...body),
      el('p',{class:'hint'},'点格子打卡；漏打的日子点一下即可补记，漏一天不会清掉之前的记录。')
    ]));
  }

  function renderEdit(){
    const d=ui.draft||{id:null,nid:uid(),name:'',target:3};
    const isNew=!d.id;
    const input=el('input',{class:'inp',type:'text',value:d.name,placeholder:'例如：早睡','aria-label':'习惯名称',
      oninput:e=>{d.name=e.target.value;},
      onkeydown:e=>{if(e.key==='Enter'&&!e.isComposing)saveHabit();}});
    const seg=el('div',{class:'seg',role:'group','aria-label':'每周目标次数'},...[1,2,3,4,5,6,7].map(n=>
      el('button',{type:'button',class:'sg'+(Number(d.target)===n?' on':''),'aria-pressed':Number(d.target)===n?'true':'false',onclick:()=>{d.target=n;redraw();}},String(n))));
    const acts=ui.confirmDel?[
      el('p',{class:'warn',role:'alert'},'⚠ 删除「'+(d.name||'')+'」及它的全部打卡记录？此操作不能撤销。'),
      el('div',{class:'acts'},
        el('button',{type:'button',class:'btn pri',disabled:!!ui.saving,onclick:deleteHabit},'确认删除'),
        el('button',{type:'button',class:'btn',onclick:()=>{ui.confirmDel=false;redraw();}},'再想想'))
    ]:[
      el('div',{class:'acts'},...kids([
        el('button',{type:'button',class:'btn pri',disabled:!!ui.saving,onclick:saveHabit},'保存'),
        el('button',{type:'button',class:'btn',onclick:closeEdit},'取消'),
        isNew?null:el('button',{type:'button',class:'btn del',onclick:()=>{ui.confirmDel=true;redraw();}},'删除习惯')
      ]))
    ];
    return el('div',{class:'form'},...kids([
      el('div',{class:'fh'},el('button',{type:'button',class:'ib','aria-label':'返回',onclick:closeEdit},'‹'),el('h2',{},isNew?'添加习惯':'编辑习惯')),
      el('label',{class:'lbl'},'习惯名称'),
      input,
      el('label',{class:'lbl'},'每周目标次数（1–7，每天最多打卡 1 次）'),
      seg,
      ui.err?el('p',{class:'err',role:'alert'},'⚠ '+ui.err):null,
      ...acts
    ]));
  }

  root.append(view==='edit'?renderEdit():renderList());
}

